  kepsek: School,
  waka_kurikulum: BookOpen,
  waka_kesiswaan: Users,
  waka_sarpras: Building2,
  kurikulum: BookOpen,
  kesiswaan: Users,
  sarpras: Building2,
  bendahara: Wallet,
  tu: Briefcase,
  guru: GraduationCap
